/*
  Full Edexcel A-level Economics A (9EC0) content pack, replacing the
  placeholder Economics entry in library-extra.js (which shipped with a flat
  7-topic list and only 6 flashcards / 4 MCQs / 3 exam questions total).

  Topic strings must match the chapter outline (ECON_GROUPS) exactly, or the
  chapter picker will filter these items out. Content is weighted toward the
  parts of 9EC0 that carry the most marks / come up most often: elasticities,
  market failure and externalities, fiscal and monetary policy, market
  structures (especially oligopoly and monopoly), and exchange rates - those
  topics carry deeper flashcard/MCQ/exam coverage than the rest.
*/

