export const ECON_FLASHCARDS = [
  { front: 'What is the economic problem?', back: 'Finite resources but infinite wants, forcing choices about how to allocate scarce resources', topic: 'Economic Methodology and the Economic Problem' },
  { front: 'What is scarcity?', back: 'The excess of human wants over what can actually be produced with available resources', topic: 'Economic Methodology and the Economic Problem' },
  { front: 'What is opportunity cost?', back: 'The value of the next best alternative forgone when making a choice', topic: 'Economic Methodology and the Economic Problem' },
  { front: 'Positive vs normative economics?', back: 'Positive = objective, testable statements of fact; normative = subjective, value-based opinions (often contain "should")', topic: 'Economic Methodology and the Economic Problem' },
  { front: "What does 'ceteris paribus' mean and why is it used?", back: "Latin for 'all other things being equal' - used to isolate the effect of one variable while holding all others constant", topic: 'Economic Methodology and the Economic Problem' },
  { front: 'What does a point inside the PPF represent?', back: 'Unemployed or underused resources - the economy is productively inefficient', topic: 'Production Possibility Frontiers' },
  { front: 'What does a point on the PPF represent?', back: 'Full and efficient use of resources - productive efficiency', topic: 'Production Possibility Frontiers' },
  { front: 'What does a point outside the PPF represent?', back: 'Currently unattainable given existing resources and technology', topic: 'Production Possibility Frontiers' },
  { front: "What causes an outward shift of a country's PPF?", back: 'Economic growth - e.g. more/better factors of production, or improved technology', topic: 'Production Possibility Frontiers' },
  { front: 'Why is a typical PPF concave (bowed outward) rather than a straight line?', back: 'It reflects increasing opportunity cost, since resources are progressively less suited to producing more of one good as more is produced', topic: 'Production Possibility Frontiers' },
  { front: 'What is a market economy?', back: 'Resource allocation decided by the price mechanism / free markets, with minimal government intervention', topic: 'Economic Systems' },
  { front: 'What is a planned (command) economy?', back: 'The government/state decides what, how and for whom to produce', topic: 'Economic Systems' },
  { front: 'What is a mixed economy?', back: 'A combination of market allocation and government intervention in resource allocation', topic: 'Economic Systems' },
  { front: 'Give one advantage of a market economy', back: 'Efficient allocation via price signals, consumer choice, and strong incentives for innovation', topic: 'Economic Systems' },
  { front: 'Give one advantage of a planned economy', back: 'Can directly address market failure and inequality, and directly ensure provision of public/merit goods', topic: 'Economic Systems' },
  { front: 'What does the rational decision-making model assume?', back: 'That consumers, firms and governments act to maximise their own self-interest (utility, profit, welfare) given available information', topic: 'Rational Decision Making' },
  { front: 'What is utility?', back: 'The satisfaction gained from consuming a good or service', topic: 'Rational Decision Making' },
  { front: 'What is the law of diminishing marginal utility?', back: 'Each additional unit consumed yields less additional satisfaction than the previous unit', topic: 'Rational Decision Making' },
  { front: 'Give one behavioural economics critique of the rational model', back: 'People are not always rational - bounded rationality and biases (e.g. anchoring, loss aversion) distort real decisions', topic: 'Rational Decision Making' },
  { front: 'What is bounded rationality?', back: 'Decision-making limited by the information, cognitive ability and time available, so people "satisfice" rather than truly optimise', topic: 'Rational Decision Making' },
  { front: 'What is demand?', back: 'The quantity of a good/service consumers are willing and able to buy at a given price in a given time period', topic: 'Demand' },
  { front: 'What is the law of demand?', back: 'As price falls, quantity demanded rises, ceteris paribus - the demand curve slopes downward', topic: 'Demand' },
  { front: 'Name three non-price determinants of demand', back: 'Any three of: income, tastes/preferences, price of substitutes/complements, population, advertising, expectations of future prices', topic: 'Demand' },
  { front: 'Movement along the demand curve vs a shift - what causes each?', back: 'Movement = caused by a change in the good’s own price; shift = caused by a change in a non-price determinant', topic: 'Demand' },
  { front: 'Normal good vs inferior good?', back: 'Normal good = demand rises as income rises; inferior good = demand falls as income rises', topic: 'Demand' },
  { front: 'What is equilibrium price?', back: 'The price at which quantity demanded equals quantity supplied, so the market clears', topic: 'Price Determination and the Price Mechanism' },
  { front: 'What happens at a price above equilibrium?', back: 'Excess supply (a surplus) develops, pushing price back down toward equilibrium', topic: 'Price Determination and the Price Mechanism' },
  { front: 'What happens at a price below equilibrium?', back: 'Excess demand (a shortage) develops, pushing price back up toward equilibrium', topic: 'Price Determination and the Price Mechanism' },
  { front: 'Name the three functions of the price mechanism', back: 'The signalling, incentive and rationing functions', topic: 'Price Determination and the Price Mechanism' },
  { front: 'What is consumer surplus?', back: 'The difference between what consumers are willing to pay and what they actually pay', topic: 'Price Determination and the Price Mechanism' },
  { front: 'What are the two key characteristics of a pure public good?', back: 'Non-excludability and non-rivalry', topic: 'Public Goods and Information Gaps' },
  { front: 'What is the free-rider problem?', back: 'People can consume a public good without paying for it since non-payers can’t be excluded, so the free market under-provides it', topic: 'Public Goods and Information Gaps' },
  { front: 'What is a quasi-public good?', back: 'A good with some but not all public good characteristics (e.g. partially excludable or rivalrous), such as a toll road', topic: 'Public Goods and Information Gaps' },
  { front: 'What is asymmetric information?', back: 'When one party in a transaction has more/better information than the other, potentially leading to market failure', topic: 'Public Goods and Information Gaps' },
  { front: 'What is moral hazard?', back: 'When a party takes on more risk because they don’t bear the full consequences of that risk (e.g. an insured person behaving more recklessly)', topic: 'Public Goods and Information Gaps' },
  { front: 'What is the purpose of an indirect tax on a good with a negative externality?', back: 'To raise revenue and/or correct the externality by raising the price and reducing quantity toward the social optimum', topic: 'Government Intervention in Markets' },
  { front: 'What is a subsidy?', back: 'A payment from government to producers that lowers costs, encouraging output/consumption of a good with positive externalities', topic: 'Government Intervention in Markets' },
  { front: 'What is a maximum price (price ceiling)?', back: 'A legal limit set below equilibrium price to make a good more affordable, which causes excess demand', topic: 'Government Intervention in Markets' },
  { front: 'What is a minimum price (price floor)?', back: 'A legal limit set above equilibrium price to protect producers/raise incomes, which causes excess supply', topic: 'Government Intervention in Markets' },
  { front: 'What is a buffer stock scheme?', back: 'A scheme where government buys and stores excess supply when price is low and releases stock when price is high, to stabilise price', topic: 'Government Intervention in Markets' },
  { front: 'What is government failure?', back: 'When government intervention leads to a net welfare loss - a less efficient allocation of resources than before intervention', topic: 'Government Failure' },
  { front: 'Give one cause of government failure', back: 'Any of: imperfect information, unintended consequences, administrative/compliance costs, political self-interest, regulatory capture', topic: 'Government Failure' },
  { front: 'What is regulatory capture?', back: 'When a regulator comes, over time, to act in the interests of the industry it regulates rather than the public', topic: 'Government Failure' },
  { front: 'What is the law of unintended consequences?', back: 'Policies often have effects that were not intended or foreseen, which can undermine or even reverse the policy’s original goal', topic: 'Government Failure' },
  { front: 'How can intervention distort price signals as a form of government failure?', back: 'Intervention (e.g. an overly generous subsidy) can cause prices to no longer accurately reflect true cost/value, causing inefficient allocation', topic: 'Government Failure' },
  { front: 'PED formula?', back: '% change in quantity demanded ÷ % change in price', topic: 'Price, Income and Cross Elasticities of Demand' },
  { front: 'What does |PED| < 1 mean?', back: 'Demand is price inelastic - quantity demanded changes proportionally less than price', topic: 'Price, Income and Cross Elasticities of Demand' },
  { front: 'What does |PED| > 1 mean?', back: 'Demand is price elastic - quantity demanded changes proportionally more than price', topic: 'Price, Income and Cross Elasticities of Demand' },
  { front: 'Name factors that make demand more price elastic', back: 'Many substitutes, a high proportion of income spent on the good, it being a luxury (not necessity), a longer time period, a narrowly defined good', topic: 'Price, Income and Cross Elasticities of Demand' },
  { front: 'YED formula?', back: '% change in quantity demanded ÷ % change in income', topic: 'Price, Income and Cross Elasticities of Demand' },
  { front: 'What does a positive YED mean?', back: 'A normal good (demand rises as income rises); YED > 1 identifies a luxury/superior good', topic: 'Price, Income and Cross Elasticities of Demand' },
  { front: 'What does a negative YED mean?', back: 'An inferior good - demand falls as income rises', topic: 'Price, Income and Cross Elasticities of Demand' },
  { front: 'XED formula?', back: '% change in quantity demanded of good A ÷ % change in price of good B', topic: 'Price, Income and Cross Elasticities of Demand' },
  { front: 'What does the sign of XED indicate?', back: 'Positive = substitutes; negative = complements (the size of the value shows how strong the relationship is)', topic: 'Price, Income and Cross Elasticities of Demand' },
  { front: 'What is supply?', back: 'The quantity of a good/service producers are willing and able to sell at a given price in a given time period', topic: 'Supply and Elasticity of Supply' },
  { front: 'What is the law of supply?', back: 'As price rises, quantity supplied rises, ceteris paribus - the supply curve slopes upward', topic: 'Supply and Elasticity of Supply' },
  { front: 'Name three non-price determinants of supply', back: 'Any three of: costs of production, technology, taxes/subsidies, number of firms, price of related goods (joint supply), weather (for agriculture)', topic: 'Supply and Elasticity of Supply' },
  { front: 'PES formula?', back: '% change in quantity supplied ÷ % change in price', topic: 'Supply and Elasticity of Supply' },
  { front: 'What makes supply more price elastic?', back: 'Spare capacity, low-cost/quickly accessible stocks, ease of switching resources between uses, a longer time period', topic: 'Supply and Elasticity of Supply' },
  { front: 'Why is supply often more inelastic in the short run than the long run?', back: 'Firms cannot vary all factors of production quickly in the short run (e.g. cannot build a new factory overnight)', topic: 'Supply and Elasticity of Supply' },
  { front: 'What is the PES of a good that cannot be stored (e.g. fresh produce or a live event) in the very short run?', back: 'Very inelastic (often near-perfectly inelastic), since output/stock can’t be adjusted', topic: 'Supply and Elasticity of Supply' },
  { front: 'Movement along the supply curve vs a shift - what causes each?', back: 'Movement = a change in the good’s own price; shift = a change in a non-price determinant (e.g. costs)', topic: 'Supply and Elasticity of Supply' },
  { front: 'What is joint supply?', back: 'When producing more of one good automatically increases the supply of another (e.g. beef and leather)', topic: 'Supply and Elasticity of Supply' },
  { front: 'What is market failure?', back: 'When the free market fails to allocate resources efficiently, leading to a net welfare loss', topic: 'Types of Market Failure' },
  { front: 'What is complete market failure?', back: 'When a missing market means a good/service is not provided at all (e.g. a pure public good)', topic: 'Types of Market Failure' },
  { front: 'What is partial market failure?', back: 'When a good is produced by the market, but at the wrong price/quantity compared to the social optimum', topic: 'Types of Market Failure' },
  { front: 'Difference between private and social costs/benefits?', back: 'Private = costs/benefits to those directly involved; social = private costs/benefits plus externalities to third parties', topic: 'Types of Market Failure' },
  { front: 'What is allocative inefficiency in the context of market failure?', back: 'Resources are not allocated to reflect consumer wants - price does not equal marginal cost (P≠MC)', topic: 'Types of Market Failure' },
  { front: 'What is a merit good?', back: 'A good under-consumed in a free market because consumers underestimate its benefits (positive information failure), e.g. education', topic: 'Types of Market Failure' },
  { front: 'What is a demerit good?', back: 'A good over-consumed in a free market because consumers underestimate its costs, or which carries negative externalities, e.g. tobacco', topic: 'Types of Market Failure' },
  { front: 'What is factor immobility and why is it a form of market failure?', back: 'When factors of production (especially labour) cannot move easily between industries/locations, causing persistent structural unemployment', topic: 'Types of Market Failure' },
  { front: 'What is the "missing market" problem?', back: 'Where no market exists at all for a good, typically because it is impossible to exclude non-payers (a pure public good)', topic: 'Types of Market Failure' },
  { front: 'What is a negative externality?', back: 'A cost imposed on a third party not involved in the transaction, not reflected in the market price (e.g. pollution)', topic: 'Externalities' },
  { front: 'What is a positive externality?', back: 'A benefit received by a third party not involved in the transaction, not reflected in the market price (e.g. education, vaccination)', topic: 'Externalities' },
  { front: 'MSC = ?', back: 'Marginal Private Cost + Marginal External Cost', topic: 'Externalities' },
  { front: 'MSB = ?', back: 'Marginal Private Benefit + Marginal External Benefit', topic: 'Externalities' },
  { front: 'With a negative production externality, is free market output too high or too low vs the social optimum?', back: 'Too high (overproduction), since MSC > MPC at the market equilibrium', topic: 'Externalities' },
  { front: 'At the social optimum with an externality present, what condition holds?', back: 'MSC = MSB (marginal social cost equals marginal social benefit)', topic: 'Externalities' },
  { front: 'With a positive consumption externality, is free market output too high or too low vs the social optimum?', back: 'Too low (underconsumption), since MSB > MPB at the market equilibrium', topic: 'Externalities' },
  { front: 'Give an example of a negative consumption externality', back: 'Passive smoking, or noise pollution from loud music late at night', topic: 'Externalities' },
  { front: 'Give an example of a positive production externality', back: 'A firm training its workers, who later benefit other employers when they change jobs', topic: 'Externalities' },
  { front: 'Define economic growth', back: 'An increase in the real value of goods/services produced in an economy over time (an increase in real GDP)', topic: 'Economic Growth' },
  { front: 'Actual growth vs potential growth?', back: 'Actual = growth in real output actually produced; potential = growth in the economy’s productive capacity (an outward PPF/LRAS shift)', topic: 'Economic Growth' },
  { front: 'Real GDP vs nominal GDP?', back: 'Real GDP is adjusted for inflation; nominal GDP is not', topic: 'Economic Growth' },
  { front: "What is the UK's technical definition of a recession?", back: 'Two or more consecutive quarters of negative real GDP growth', topic: 'Economic Growth' },
  { front: 'What is the output gap?', back: 'The difference between actual and potential (trend) output; positive = economy overheating, negative = spare capacity', topic: 'Economic Growth' },
  { front: 'Define inflation', back: 'A sustained rise in the general price level over time', topic: 'Inflation' },
  { front: 'What is CPI?', back: 'The Consumer Prices Index - measures the average change in prices of a representative basket of goods/services', topic: 'Inflation' },
  { front: 'Deflation vs disinflation?', back: 'Deflation = a falling general price level; disinflation = a falling RATE of inflation (prices still rising, just more slowly)', topic: 'Inflation' },
  { front: 'Name one cost of inflation', back: 'Any of: menu costs, shoe-leather costs, redistribution from savers to borrowers, loss of international competitiveness', topic: 'Inflation' },
  { front: 'Demand-pull vs cost-push inflation?', back: 'Demand-pull = caused by excess demand (AD growing faster than AS); cost-push = caused by rising production costs shifting AS left', topic: 'Inflation' },
  { front: 'Define unemployment', back: 'People of working age who are without a job, actively seeking work and available to start', topic: 'Employment and Unemployment' },
  { front: 'What is the claimant count?', back: 'The number of people claiming unemployment-related benefits', topic: 'Employment and Unemployment' },
  { front: 'What is the Labour Force Survey (ILO) measure?', back: 'An internationally comparable survey-based measure of unemployment, based on job search/availability rather than benefit claims', topic: 'Employment and Unemployment' },
  { front: 'Name one type of unemployment and define it', back: 'e.g. structural (long-term decline in an industry leaving workers with the wrong skills), frictional (short-term, between jobs), cyclical (caused by a fall in AD), or seasonal', topic: 'Employment and Unemployment' },
  { front: 'What is the "economically inactive" population?', back: 'People of working age who are neither employed nor unemployed (not seeking work), e.g. students, retirees, carers', topic: 'Employment and Unemployment' },
  { front: "What is the balance of payments?", back: "A record of all financial transactions between a country's residents and the rest of the world over a period", topic: 'Balance of Payments' },
  { front: 'What are the two main accounts of the balance of payments?', back: 'The current account and the capital/financial account', topic: 'Balance of Payments' },
  { front: 'What does the current account record?', back: 'Trade in goods and services, primary income (e.g. investment income), and secondary income (e.g. remittances, transfers)', topic: 'Balance of Payments' },
  { front: 'What is a current account deficit?', back: 'When the value of imports plus outflows exceeds exports plus inflows - the country is a net borrower from the rest of the world', topic: 'Balance of Payments' },
  { front: 'How must a current account deficit be balanced?', back: 'By a surplus on the financial/capital account (a net inflow of foreign investment/borrowing)', topic: 'Balance of Payments' },
  { front: 'AD formula?', back: 'AD = C + I + G + (X-M)', topic: 'Components of Aggregate Demand' },
  { front: 'What is C in the AD equation?', back: 'Consumer expenditure - consumption spending by households', topic: 'Components of Aggregate Demand' },
  { front: 'What is I in the AD equation?', back: 'Investment - spending by firms on capital goods', topic: 'Components of Aggregate Demand' },
  { front: 'What is G in the AD equation?', back: 'Government spending on goods and services', topic: 'Components of Aggregate Demand' },
  { front: 'What is (X-M) in the AD equation?', back: 'Net exports - exports minus imports', topic: 'Components of Aggregate Demand' },
  { front: 'What is the marginal propensity to consume (MPC)?', back: 'The proportion of an extra unit of income that is spent rather than saved', topic: 'Consumption, Savings and Investment' },
  { front: 'What is the accelerator effect?', back: 'The theory that investment depends on the RATE OF CHANGE of national income/demand, not just its level', topic: 'Consumption, Savings and Investment' },
  { front: 'Name a determinant of consumption', back: 'Any of: disposable income, interest rates, consumer confidence, wealth', topic: 'Consumption, Savings and Investment' },
  { front: 'Name a determinant of investment', back: 'Any of: interest rates, business confidence, rate of economic growth, corporation tax', topic: 'Consumption, Savings and Investment' },
  { front: 'How do interest rates affect investment?', back: 'Higher interest rates raise the cost of borrowing/opportunity cost of funds, reducing investment (an inverse relationship)', topic: 'Consumption, Savings and Investment' },
  { front: 'What does aggregate supply (AS) represent?', back: 'The total quantity of goods/services producers are willing and able to supply at a given price level in a given time period', topic: 'Aggregate Supply' },
  { front: 'Shape of the SRAS curve?', back: 'Upward sloping - higher prices increase profitability, incentivising more output in the short run', topic: 'Aggregate Supply' },
  { front: 'Shape of LRAS in the classical view?', back: 'Vertical at full employment/potential output - in the long run, output is determined by productive capacity, not price level', topic: 'Aggregate Supply' },
  { front: 'Shape of LRAS in the Keynesian view?', back: 'Elastic (near-horizontal) with spare capacity, curving upward and eventually becoming vertical near full capacity', topic: 'Aggregate Supply' },
  { front: 'Name a factor that increases LRAS', back: 'Any of: improved technology, increased quantity/quality of factors of production, deregulation', topic: 'Aggregate Supply' },
  { front: 'What are injections into the circular flow of income?', back: 'Investment, government spending and exports (I, G, X)', topic: 'The Circular Flow of Income and the Multiplier' },
  { front: 'What are withdrawals (leakages) from the circular flow of income?', back: 'Savings, taxation and imports (S, T, M)', topic: 'The Circular Flow of Income and the Multiplier' },
  { front: 'Multiplier formula using MPS?', back: 'k = 1 / MPS (equivalently 1 / (1 - MPC), in a simplified economy)', topic: 'The Circular Flow of Income and the Multiplier' },
  { front: 'What does the multiplier effect describe?', back: 'An initial change in an injection leads to a larger final change in national income', topic: 'The Circular Flow of Income and the Multiplier' },
  { front: 'What increases the size of the multiplier?', back: 'A lower marginal propensity to withdraw (lower MPS+MPT+MPM) - more of extra income being re-spent domestically', topic: 'The Circular Flow of Income and the Multiplier' },
  { front: 'Name a demand-side cause of short-run growth', back: 'A rise in any component of AD (C, I, G, or X-M)', topic: 'Causes and Effects of Economic Growth' },
  { front: 'Name a supply-side cause of long-run growth', back: 'Increased quantity/quality of factors of production, or technological progress', topic: 'Causes and Effects of Economic Growth' },
  { front: 'Name a benefit of economic growth', back: 'Any of: higher living standards, more jobs, higher tax revenue/lower deficit', topic: 'Causes and Effects of Economic Growth' },
  { front: 'Name a cost of economic growth', back: 'Any of: inflation risk, environmental damage, increased inequality, resource depletion', topic: 'Causes and Effects of Economic Growth' },
  { front: 'How do actual and potential growth relate to their causes?', back: 'Actual growth (short-run, demand-driven, a movement toward the PPF) vs potential growth (long-run, supply-driven, an outward shift of the PPF)', topic: 'Causes and Effects of Economic Growth' },
  { front: 'Name the four main UK macroeconomic objectives', back: 'Economic growth, low unemployment, low and stable inflation, and balance of payments equilibrium (often also: a balanced government budget and income equality)', topic: 'Macroeconomic Objectives' },
  { front: "What is the UK's inflation target?", back: '2% (CPI), set by the government for the Bank of England to meet', topic: 'Macroeconomic Objectives' },
  { front: 'What is a policy conflict?', back: 'When achieving one macroeconomic objective makes achieving another more difficult', topic: 'Macroeconomic Objectives' },
  { front: 'Give an example of a policy conflict', back: 'Boosting growth/reducing unemployment via looser policy can raise inflation and worsen the balance of payments', topic: 'Macroeconomic Objectives' },
  { front: 'What is the "magic diamond" used for?', back: 'A visual tool to compare a country’s performance across the four main macroeconomic objectives at a glance', topic: 'Macroeconomic Objectives' },
  { front: 'What is supply-side policy?', back: 'Policy aimed at increasing the productive capacity of the economy (shifting LRAS right) rather than managing demand', topic: 'Supply-Side Policy' },
  { front: 'Give an example of a market-based supply-side policy', back: 'Any of: deregulation, privatisation, reducing income tax to boost work incentives, reducing trade union power', topic: 'Supply-Side Policy' },
  { front: 'Give an example of an interventionist supply-side policy', back: 'Any of: government spending on education/training, infrastructure investment, R&D subsidies/support for innovation', topic: 'Supply-Side Policy' },
  { front: 'What is the aim of supply-side policy on the AS/AD diagram?', back: 'To shift the LRAS curve to the right, increasing potential output without increasing inflationary pressure', topic: 'Supply-Side Policy' },
  { front: 'Why do supply-side policies often take a long time to have an effect?', back: 'Improvements like education/infrastructure investment take years to feed through into higher productive capacity', topic: 'Supply-Side Policy' },
  { front: 'Define fiscal policy', back: 'The use of government spending and taxation to influence aggregate demand and the economy', topic: 'Fiscal Policy' },
  { front: 'What is expansionary fiscal policy?', back: 'Increased government spending and/or reduced taxation, aiming to increase AD (used to boost growth/reduce unemployment)', topic: 'Fiscal Policy' },
  { front: 'What is contractionary (deflationary) fiscal policy?', back: 'Reduced government spending and/or increased taxation, aiming to reduce AD (used to control inflation/reduce a deficit)', topic: 'Fiscal Policy' },
  { front: 'What is a budget deficit?', back: 'When government spending exceeds tax revenue in a given year', topic: 'Fiscal Policy' },
  { front: 'What is the national debt?', back: 'The total accumulated stock of government borrowing built up over time (the sum of past deficits)', topic: 'Fiscal Policy' },
  { front: 'What is a progressive tax?', back: 'A tax where the proportion of income paid rises as income rises (e.g. UK income tax)', topic: 'Fiscal Policy' },
  { front: 'What is a regressive tax?', back: 'A tax where the proportion of income paid falls as income rises (e.g. many indirect taxes)', topic: 'Fiscal Policy' },
  { front: 'What is an automatic stabiliser?', back: 'A fiscal mechanism that automatically counteracts fluctuations in the economic cycle without new government action, e.g. unemployment benefits rising in a downturn', topic: 'Fiscal Policy' },
  { front: 'What is discretionary fiscal policy?', back: 'Deliberate, active changes to spending/taxation by government, as opposed to automatic stabilisers', topic: 'Fiscal Policy' },
  { front: 'Define monetary policy', back: 'The use of interest rates, money supply and exchange rate to influence aggregate demand and the economy, usually set by the central bank', topic: 'Monetary Policy' },
  { front: 'Who sets UK interest rates?', back: "The Bank of England's Monetary Policy Committee (MPC)", topic: 'Monetary Policy' },
  { front: 'What is the Bank Rate?', back: 'The main interest rate set by the Bank of England, which influences other interest rates across the economy', topic: 'Monetary Policy' },
  { front: 'How does a rise in interest rates affect AD?', back: 'It raises the cost of borrowing and reward for saving, reducing consumption and investment, appreciates the exchange rate (reducing net exports) - all reducing AD', topic: 'Monetary Policy' },
  { front: 'What is quantitative easing (QE)?', back: 'A central bank creating new money to buy financial assets (e.g. government bonds), increasing money supply and lowering long-term interest rates to stimulate the economy', topic: 'Monetary Policy' },
  { front: 'What is the "transmission mechanism" of monetary policy?', back: 'The chain of effects through which a change in interest rates eventually affects inflation/output (via consumption, investment, exchange rate, asset prices, expectations)', topic: 'Monetary Policy' },
  { front: 'What is the effect of a rate cut on the exchange rate?', back: 'It tends to depreciate the currency, since lower returns make holding that currency less attractive to foreign investors', topic: 'Monetary Policy' },
  { front: 'Why might monetary policy be less effective at very low interest rates ("liquidity trap")?', back: 'Rates are already near zero, leaving little room for further cuts to stimulate demand, so unconventional tools like QE are used instead', topic: 'Monetary Policy' },
  { front: 'What is meant by central bank independence?', back: 'The central bank sets interest rates free from direct political interference, aiming for credible, consistent pursuit of the inflation target', topic: 'Monetary Policy' },
  { front: 'What is organic (internal) growth?', back: "Growth achieved by expanding a firm's own operations/output, e.g. by reinvesting profit", topic: 'Business Growth' },
  { front: 'What is inorganic (external) growth?', back: 'Growth achieved via mergers and acquisitions with other firms', topic: 'Business Growth' },
  { front: 'What is horizontal integration?', back: 'A merger between firms at the same stage of production in the same industry (e.g. two supermarkets)', topic: 'Business Growth' },
  { front: 'What is forward vertical integration?', back: 'A merger with a firm further forward in the supply chain, closer to the consumer (e.g. a manufacturer buying a retailer)', topic: 'Business Growth' },
  { front: 'What is backward vertical integration?', back: 'A merger with a firm further back in the supply chain, closer to raw materials (e.g. a manufacturer buying a supplier)', topic: 'Business Growth' },
  { front: 'What is a demerger?', back: 'When a firm splits into two or more separate, independent companies', topic: 'Demergers' },
  { front: 'Give one reason for a demerger', back: 'To focus on core business activities/improve efficiency, satisfy competition authorities, or unlock shareholder value', topic: 'Demergers' },
  { front: 'What is divestment?', back: 'Selling off a subsidiary or division of a business', topic: 'Demergers' },
  { front: 'What diseconomy of scale might trigger a demerger?', back: 'Difficulties of managing a very large/diverse organisation, e.g. communication problems or loss of control', topic: 'Demergers' },
  { front: "What might happen to a firm's share price after a well-received demerger?", back: 'It could rise, if investors believe the separate parts are worth more individually (a "sum of the parts" effect)', topic: 'Demergers' },
  { front: 'What is the traditional assumption about a firm’s objective?', back: 'Profit maximisation - producing where MC=MR', topic: 'Business Objectives' },
  { front: 'What is revenue maximisation?', back: 'Maximising total revenue rather than profit, typically at the output where MR=0', topic: 'Business Objectives' },
  { front: 'What is sales/growth maximisation?', back: 'Maximising sales volume/market share, often subject to a minimum profit constraint', topic: 'Business Objectives' },
  { front: 'What is satisficing?', back: 'Aiming for a satisfactory (rather than maximum) level of profit, balancing the interests of multiple stakeholders', topic: 'Business Objectives' },
  { front: 'What is the principal-agent problem?', back: 'A conflict of interest between owners (principals, wanting profit maximisation) and managers (agents, who may pursue their own goals like growth or status)', topic: 'Business Objectives' },
  { front: 'Total revenue formula?', back: 'Price × quantity sold', topic: 'Revenue, Costs and Profit' },
  { front: 'What is marginal revenue?', back: 'The extra revenue from selling one more unit', topic: 'Revenue, Costs and Profit' },
  { front: 'Fixed costs vs variable costs?', back: "Fixed = don't change with output (e.g. rent); variable = change directly with output (e.g. raw materials)", topic: 'Revenue, Costs and Profit' },
  { front: 'What is normal profit?', back: 'The minimum profit needed to keep a firm in its current line of business (the opportunity cost of capital/enterprise); it is covered within average cost', topic: 'Revenue, Costs and Profit' },
  { front: 'What is supernormal (abnormal) profit?', back: 'Profit above normal profit - where AR > AC', topic: 'Revenue, Costs and Profit' },
  { front: 'What are economies of scale?', back: 'Falling long-run average costs as output/scale of production increases', topic: 'Economies and Diseconomies of Scale' },
  { front: 'Name one internal economy of scale', back: 'Any of: purchasing/bulk-buying economies, technical economies, managerial economies, financial economies, risk-bearing economies', topic: 'Economies and Diseconomies of Scale' },
  { front: 'What are diseconomies of scale?', back: 'Rising long-run average costs as output/scale increases beyond a certain point', topic: 'Economies and Diseconomies of Scale' },
  { front: 'Give one cause of diseconomies of scale', back: 'Any of: communication problems, loss of control/coordination difficulties, worker alienation/lower morale', topic: 'Economies and Diseconomies of Scale' },
  { front: 'What is the minimum efficient scale (MES)?', back: 'The lowest output level at which a firm can achieve the lowest possible long-run average cost', topic: 'Economies and Diseconomies of Scale' },
  { front: 'Name one assumption of perfect competition', back: 'Any of: many buyers/sellers, homogeneous product, perfect information, freedom of entry/exit', topic: 'Perfect Competition' },
  { front: "Why are perfectly competitive firms 'price takers'?", back: 'Each firm is too small relative to the market to influence the market price - they must accept the price set by market forces', topic: 'Perfect Competition' },
  { front: 'Short-run profit-maximising condition for any firm?', back: 'MC = MR', topic: 'Perfect Competition' },
  { front: 'What happens to supernormal profit in the long run under perfect competition?', back: 'It is competed away to zero (normal profit only) as new firms enter, shifting supply right and lowering price', topic: 'Perfect Competition' },
  { front: 'Shape of the demand curve facing an individual firm in perfect competition?', back: 'Perfectly elastic (horizontal) at the market price', topic: 'Perfect Competition' },
  { front: 'Name one characteristic of monopolistic competition', back: 'Any of: many firms, low barriers to entry/exit, differentiated products', topic: 'Monopolistic Competition' },
  { front: 'How do firms in monopolistic competition compete, other than on price?', back: 'Non-price competition - branding, product differentiation, quality, advertising', topic: 'Monopolistic Competition' },
  { front: 'Does a firm in monopolistic competition face a downward or perfectly elastic demand curve?', back: 'Downward sloping, due to product differentiation/brand loyalty giving some price-setting power', topic: 'Monopolistic Competition' },
  { front: 'What happens to supernormal profit in the long run under monopolistic competition?', back: 'It is competed away to normal profit as new firms enter, attracted by supernormal profits', topic: 'Monopolistic Competition' },
  { front: 'Give an example of an industry resembling monopolistic competition', back: 'e.g. restaurants, hairdressers, or other retail with many small differentiated firms', topic: 'Monopolistic Competition' },
  { front: 'What is an oligopoly?', back: 'A market dominated by a few large firms, with high barriers to entry', topic: 'Oligopoly' },
  { front: 'What is a concentration ratio?', back: 'The proportion of total market output/sales accounted for by the largest firms (e.g. a 5-firm concentration ratio)', topic: 'Oligopoly' },
  { front: 'What is interdependence in an oligopoly?', back: "Firms must consider rivals' likely reactions when making decisions, since actions by one firm significantly affect others", topic: 'Oligopoly' },
  { front: 'What is collusion?', back: 'When firms agree (openly or tacitly) to coordinate behaviour, e.g. fix prices or limit output, rather than compete', topic: 'Oligopoly' },
  { front: 'Overt vs tacit collusion?', back: 'Overt = explicit, often illegal agreement (a cartel); tacit = implicit coordination without direct communication, e.g. price leadership', topic: 'Oligopoly' },
  { front: 'What does the kinked demand curve model illustrate?', back: 'Price rigidity in oligopoly - firms assume rivals will match a price cut but not a price rise, making the demand curve kinked at the current price', topic: 'Oligopoly' },
  { front: 'What is price leadership?', back: 'When one dominant firm sets the price and others follow, avoiding direct price competition', topic: 'Oligopoly' },
  { front: 'Name a form of non-price competition in oligopoly', back: 'Any of: advertising, branding, loyalty schemes, product innovation', topic: 'Oligopoly' },
  { front: 'What is a cartel?', back: 'A formal agreement between firms to fix prices or limit output, usually illegal under competition law', topic: 'Oligopoly' },
  { front: 'What is a pure monopoly?', back: 'A market with a single seller/producer controlling 100% of market share (UK competition law often treats 25%+ share as "monopoly power")', topic: 'Monopoly' },
  { front: 'Name a barrier to entry that can create/protect a monopoly', back: 'Any of: legal barriers (patents), high sunk costs, control of essential resources, economies of scale', topic: 'Monopoly' },
  { front: "What is a monopolist's profit-maximising condition, and how does its price compare to MC?", back: 'MC=MR, but price is set ABOVE marginal cost since AR>MR under a downward-sloping demand curve', topic: 'Monopoly' },
  { front: 'What is a natural monopoly?', back: 'A market where it is most efficient for a single firm to supply the whole market due to very high fixed costs/economies of scale (e.g. water pipelines)', topic: 'Monopoly' },
  { front: 'What is price discrimination?', back: 'Charging different prices to different consumers/groups for the same good, not based on cost differences', topic: 'Monopoly' },
  { front: 'Name one condition needed for price discrimination', back: 'Market power, ability to separate markets, and different price elasticities of demand between groups', topic: 'Monopoly' },
  { front: 'What is X-inefficiency?', back: 'A lack of competitive pressure allowing a monopolist to operate with higher costs than necessary (not minimising costs)', topic: 'Monopoly' },
  { front: 'What is a potential benefit of monopoly?', back: 'Economies of scale lowering costs, or supernormal profits funding R&D/innovation', topic: 'Monopoly' },
  { front: 'What is a potential cost of monopoly to consumers?', back: 'Higher prices and lower output than under competition, and allocative/productive inefficiency', topic: 'Monopoly' },
  { front: 'What is a contestable market?', back: 'A market with low barriers to entry and exit, even if few firms currently operate in it', topic: 'Contestability' },
  { front: 'What is a "hit and run" entrant?', back: 'A firm that enters a contestable market to exploit supernormal profits, then exits quickly if conditions change, without incurring significant sunk costs', topic: 'Contestability' },
  { front: 'What is a sunk cost?', back: 'A cost that cannot be recovered once incurred, e.g. specialised machinery with no resale value', topic: 'Contestability' },
  { front: 'Why do low sunk costs increase contestability?', back: 'They reduce the risk/cost of entering and exiting a market, making entry (and the threat of entry) more credible', topic: 'Contestability' },
  { front: 'What effect does high contestability have on incumbent firm behaviour?', back: 'It can force incumbents to behave more competitively (lower prices, closer to normal profit) even without actual new entry, due to the threat of entry', topic: 'Contestability' },
  { front: 'In a competitive labour market, what determines the equilibrium wage?', back: 'The intersection of labour demand and labour supply', topic: 'Wage Determination' },
  { front: 'What determines demand for labour?', back: "Derived demand - based on the demand for the good/service labour produces, and labour's marginal revenue product (MRP)", topic: 'Wage Determination' },
  { front: 'What is marginal revenue product (MRP) of labour?', back: 'The extra revenue generated by employing one more unit of labour', topic: 'Wage Determination' },
  { front: 'Name one factor that increases labour supply to an occupation', back: 'Any of: higher relative wages, lower training requirements/barriers to entry, improved working conditions', topic: 'Wage Determination' },
  { front: 'What effect does a trade union have on wages in a competitive labour market?', back: 'Can raise wages above the competitive equilibrium by restricting labour supply or bargaining collectively, though this may reduce employment', topic: 'Wage Determination' },
  { front: 'What is a monopsony employer?', back: 'A single (or dominant) buyer of labour in a market, with power to set wages below the competitive level', topic: 'Labour Market Issues' },
  { front: 'What effect can a national minimum wage have in a monopsony labour market?', back: 'It can increase BOTH wages and employment (unlike in a competitive market), up to a certain level, by countering the monopsonist’s wage-setting power', topic: 'Labour Market Issues' },
  { front: 'What is occupational immobility of labour?', back: 'Workers lacking the skills/qualifications to move between different types of jobs', topic: 'Labour Market Issues' },
  { front: 'What is geographical immobility of labour?', back: 'Workers being unable/unwilling to relocate to where jobs are available', topic: 'Labour Market Issues' },
  { front: 'What is the gender pay gap?', back: 'The difference in average earnings between men and women, arising from a mix of discrimination and other factors (e.g. differing industries/hours/career breaks)', topic: 'Labour Market Issues' },
  { front: 'Difference between equity and equality?', back: 'Equity = fairness (may involve unequal treatment to achieve a fair outcome); equality = treating everyone the same/identically', topic: 'Government Intervention and Equity' },
  { front: 'Name one policy used to reduce income/wealth inequality', back: 'Any of: progressive taxation, means-tested benefits, national minimum wage, inheritance tax', topic: 'Government Intervention and Equity' },
  { front: 'What is the Gini coefficient used for?', back: 'Measuring income/wealth inequality within a country - 0 = perfect equality, 1 = perfect inequality', topic: 'Government Intervention and Equity' },
  { front: 'What is a Lorenz curve?', back: 'A graph showing the cumulative share of income/wealth held by cumulative shares of the population, used to illustrate inequality', topic: 'Government Intervention and Equity' },
  { front: 'Name one argument against government intervention to redistribute income', back: 'Can reduce incentives to work/invest (the efficiency-equity trade-off), or be costly/bureaucratic to administer', topic: 'Government Intervention and Equity' },
  { front: 'What is comparative advantage?', back: 'The ability of a country to produce a good at a lower opportunity cost than another country', topic: 'International Trade' },
  { front: 'Why does trade based on comparative advantage benefit both countries?', back: 'Specialisation and trade allow total global output to increase, letting both trading partners consume more than they could in isolation', topic: 'International Trade' },
  { front: 'What is absolute advantage?', back: 'The ability to produce more of a good using the same resources than another country (differs from comparative advantage, which is about opportunity cost)', topic: 'International Trade' },
  { front: 'Name one benefit of free trade', back: 'Any of: lower prices/greater choice for consumers, access to larger markets/economies of scale for firms, increased competition driving efficiency', topic: 'International Trade' },
  { front: 'Name one cost/criticism of free trade', back: 'Any of: structural unemployment in import-competing industries, risk of increased inequality, over-reliance on foreign supply chains', topic: 'International Trade' },
  { front: 'What is a trading bloc?', back: 'A group of countries that agree to reduce/remove trade barriers between themselves', topic: 'Trading Blocs and the WTO' },
  { front: 'Free trade area vs customs union?', back: 'Free trade area = members remove tariffs/quotas between themselves but set their own external trade policy; customs union = members also adopt a common external tariff on non-members', topic: 'Trading Blocs and the WTO' },
  { front: 'What is trade creation?', back: 'When joining a trading bloc shifts consumption from a higher-cost domestic producer to a lower-cost producer within the bloc, increasing efficiency', topic: 'Trading Blocs and the WTO' },
  { front: 'What is trade diversion?', back: 'When joining a trading bloc shifts consumption from a lower-cost producer outside the bloc to a higher-cost producer inside the bloc, reducing efficiency', topic: 'Trading Blocs and the WTO' },
  { front: "What is the WTO's main role?", back: 'To promote free trade globally, oversee trade agreements between member countries, and resolve trade disputes', topic: 'Trading Blocs and the WTO' },
  { front: 'Under floating exchange rates, how might a current account deficit self-correct?', back: 'A deficit puts downward pressure on the currency (depreciation), making exports cheaper/imports dearer, which should improve the trade balance over time', topic: 'The Balance of Payments' },
  { front: 'Name one expenditure-switching policy to correct a deficit', back: 'Depreciation/devaluation of the currency, or import tariffs - aims to switch spending from foreign to domestic goods', topic: 'The Balance of Payments' },
  { front: 'Name one expenditure-reducing policy to correct a deficit', back: 'Contractionary fiscal/monetary policy, reducing domestic demand (including demand for imports)', topic: 'The Balance of Payments' },
  { front: 'What is the Marshall-Lerner condition?', back: 'A depreciation will improve the trade balance only if the sum of the price elasticities of demand for exports and imports is greater than 1', topic: 'The Balance of Payments' },
  { front: 'What is the J-curve effect?', back: 'The theory that a depreciation initially WORSENS the trade balance (inelastic demand in the short run) before IMPROVING it once demand adjusts', topic: 'The Balance of Payments' },
  { front: 'Absolute poverty vs relative poverty?', back: "Absolute = income below a fixed threshold needed for basic needs; relative = income significantly below the average/median in a specific society", topic: 'Poverty and Inequality' },
  { front: "What is the World Bank's international extreme poverty line (approx)?", back: 'Around $2.15 a day (figure updated periodically)', topic: 'Poverty and Inequality' },
  { front: 'Name one cause of poverty in developing countries', back: 'Any of: low economic growth, poor education/healthcare access, conflict/political instability, corruption', topic: 'Poverty and Inequality' },
  { front: 'Name one policy to reduce poverty', back: 'Any of: economic growth/job creation, targeted cash transfers, investment in education/healthcare, microfinance', topic: 'Poverty and Inequality' },
  { front: 'Difference between income inequality and wealth inequality?', back: 'Income = the flow of earnings received over a period; wealth = the stock of assets owned at a point in time - wealth inequality is typically more extreme', topic: 'Poverty and Inequality' },
  { front: 'Name one measure of development other than GDP per capita', back: 'The Human Development Index (HDI), which combines income, education and health', topic: 'Measures and Strategies for Development' },
  { front: 'What does the HDI measure?', back: 'A composite index combining income, education (literacy/schooling) and life expectancy to give a broader measure of development than income alone', topic: 'Measures and Strategies for Development' },
  { front: 'What is a strength of using HDI over GDP per capita?', back: 'It captures wider aspects of wellbeing (health, education), not just income', topic: 'Measures and Strategies for Development' },
  { front: 'Name one interventionist strategy for development', back: 'Any of: investment in infrastructure, education/healthcare spending, industrialisation policy', topic: 'Measures and Strategies for Development' },
  { front: 'Name one market-based/free-market strategy for development', back: 'Any of: trade liberalisation, attracting foreign direct investment (FDI), privatisation', topic: 'Measures and Strategies for Development' },
  { front: 'Name one function of financial markets', back: 'Any of: facilitating saving, lending/borrowing, allocating capital to its most productive use, enabling risk management/insurance', topic: 'The Role of Financial Markets' },
  { front: 'What is a financial market?', back: 'A market where buyers and sellers trade financial assets, such as shares, bonds, and currencies', topic: 'The Role of Financial Markets' },
  { front: "What is asymmetric information's relevance to financial markets?", back: 'Lenders/investors often know less than borrowers about the true risk of a loan/investment, which can cause market failure (e.g. mispriced risk)', topic: 'The Role of Financial Markets' },
  { front: "What is moral hazard's relevance to financial markets?", back: "Financial institutions expecting to be bailed out if they fail may take excessive risks, since they don't bear the full downside consequences", topic: 'The Role of Financial Markets' },
  { front: 'What is systemic risk?', back: 'The risk that the failure of one financial institution triggers a cascading failure across the wider financial system', topic: 'The Role of Financial Markets' },
  { front: 'Name one role of a central bank besides setting interest rates', back: 'Any of: acting as "lender of last resort", regulating/supervising financial institutions, managing the currency/reserves', topic: 'Central Banks and Financial Regulation' },
  { front: 'What is "lender of last resort"?', back: "The central bank's role of providing emergency funding to solvent but illiquid banks to prevent a banking system collapse", topic: 'Central Banks and Financial Regulation' },
  { front: 'What is macroprudential regulation?', back: 'Regulation aimed at the stability of the WHOLE financial system, rather than just individual institutions (microprudential regulation)', topic: 'Central Banks and Financial Regulation' },
  { front: 'Give an example of a macroprudential tool', back: 'Capital requirements (minimum capital banks must hold as a buffer against losses), or loan-to-value/loan-to-income limits on mortgages', topic: 'Central Banks and Financial Regulation' },
  { front: 'Why is financial regulation needed?', back: 'To reduce systemic risk, protect consumers/depositors, and correct market failures like asymmetric information and moral hazard', topic: 'Central Banks and Financial Regulation' },
  { front: 'Name one type of public expenditure', back: 'Capital spending (e.g. infrastructure), current spending (e.g. public sector wages), or transfer payments (e.g. pensions/benefits)', topic: 'Public Expenditure and Taxation' },
  { front: 'What is a transfer payment?', back: 'A payment from government for which no good/service is received in return (e.g. pensions, unemployment benefits) - not counted directly in GDP', topic: 'Public Expenditure and Taxation' },
  { front: 'What is the Laffer curve used to illustrate?', back: 'That beyond a certain tax rate, further increases can actually REDUCE total tax revenue, as high rates discourage work/investment or encourage avoidance', topic: 'Public Expenditure and Taxation' },
  { front: 'Name one argument for higher public spending', back: 'Corrects market failure/provides public and merit goods, reduces inequality, supports long-run growth via infrastructure/education investment', topic: 'Public Expenditure and Taxation' },
  { front: 'Name one argument against higher public spending', back: 'Requires higher taxes/borrowing, risk of crowding out private sector activity, risk of inefficient/wasteful spending', topic: 'Public Expenditure and Taxation' },
  { front: 'What is the national debt?', back: 'The total accumulated stock of government borrowing, built up from the sum of past budget deficits (minus any surpluses)', topic: 'The National Debt' },
  { front: 'What is the debt-to-GDP ratio used for?', back: "Measuring the size of a country's national debt relative to the size of its economy, allowing comparison over time/between countries", topic: 'The National Debt' },
  { front: 'Name one risk of a high national debt', back: 'Rising interest payments crowding out other public spending, risk of investors demanding higher interest rates, reduced fiscal flexibility in future crises', topic: 'The National Debt' },
  { front: 'How can economic growth help reduce the debt-to-GDP ratio?', back: 'Growth increases GDP (the denominator) and raises tax revenue, both of which can help stabilise or reduce the ratio even without repaying debt', topic: 'The National Debt' },
  { front: 'What is "austerity" in a fiscal policy context?', back: 'A period of significant government spending cuts and/or tax rises aimed at reducing a budget deficit/national debt', topic: 'The National Debt' },
  { front: 'What is an exchange rate?', back: 'The price of one currency expressed in terms of another currency', topic: 'Exchange Rates' },
  { front: 'What is a floating exchange rate?', back: 'A rate determined purely by market forces of supply and demand for the currency, with no government/central bank intervention', topic: 'Exchange Rates' },
  { front: 'What is a fixed exchange rate?', back: 'A rate pegged by the government/central bank to another currency (or basket of currencies), maintained through intervention', topic: 'Exchange Rates' },
  { front: 'What is currency appreciation?', back: 'A rise in the value of a currency relative to another currency (under a floating system)', topic: 'Exchange Rates' },
  { front: 'What is currency depreciation?', back: 'A fall in the value of a currency relative to another currency (under a floating system)', topic: 'Exchange Rates' },
  { front: 'What effect does depreciation have on exports and imports?', back: 'Exports become cheaper for foreign buyers (more competitive); imports become more expensive for domestic buyers', topic: 'Exchange Rates' },
  { front: 'Name one factor that affects the exchange rate', back: 'Any of: relative interest rates, relative inflation rates, the current account balance, speculation, relative economic growth', topic: 'Exchange Rates' },
  { front: 'What is competitive devaluation ("currency war")?', back: 'When countries deliberately weaken their currency to gain a trade advantage, potentially prompting retaliatory devaluations by other countries', topic: 'Exchange Rates' },
  { front: 'What is a managed float?', back: 'An exchange rate mostly determined by market forces, but with occasional central bank intervention to influence its value', topic: 'Exchange Rates' },
]

